const fs = require('fs');
const path = require('path');
const cp = require('child_process');

const ROOT = process.cwd();
const MOBILE = path.join(ROOT, 'mobile');
const SRC = path.join(MOBILE, 'src');

const entry = path.join(SRC, 'screens', 'EntryFormScreen.tsx');
const collection = path.join(SRC, 'screens', 'CollectionDetailsScreen.tsx');
const topic = path.join(SRC, 'screens', 'TopicDetailsScreen.tsx');
const radio = path.join(SRC, 'screens', 'MemoryRadioScreen.tsx');
const glyph = path.join(SRC, 'components', 'ShareGlyph.tsx');

for (const file of [entry, collection, topic, radio, glyph]) {
  if (!fs.existsSync(file)) {
    throw new Error('SAFE STOP - missing ' + path.relative(ROOT, file));
  }
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-');
const backupDir = path.join(
  ROOT,
  '_recovery',
  'share-clean-v2-' + stamp,
);

fs.mkdirSync(backupDir, { recursive: true });

for (const file of [entry, collection, topic, radio, glyph]) {
  fs.copyFileSync(
    file,
    path.join(backupDir, path.basename(file)),
  );
}

const assetDir = path.join(MOBILE, 'assets');
fs.mkdirSync(assetDir, { recursive: true });

const assetFile = path.join(
  assetDir,
  'ljingle-share-icon-clean.png',
);

fs.writeFileSync(
  assetFile,
  Buffer.from('', 'base64'),
);

function read(file) {
  return fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
}

function write(file, text) {
  fs.writeFileSync(file, text, 'utf8');
}

function fail(message) {
  throw new Error('SAFE STOP - ' + message);
}

function replaceStyleObject(text, key, replacement) {
  const marker = '  ' + key + ':';
  const start = text.indexOf(marker);

  if (start < 0) return text;

  const braceStart = text.indexOf('{', start);
  if (braceStart < 0) fail('style brace missing: ' + key);

  let depth = 0;
  let endBrace = -1;

  for (let i = braceStart; i < text.length; i += 1) {
    if (text[i] === '{') depth += 1;
    if (text[i] === '}') {
      depth -= 1;
      if (depth === 0) {
        endBrace = i;
        break;
      }
    }
  }

  if (endBrace < 0) fail('style close missing: ' + key);

  let end = endBrace + 1;
  if (text[end] === ',') end += 1;

  return (
    text.slice(0, start) +
    replacement +
    text.slice(end)
  );
}

// ---------------------------------------------------------------------------
// 1) Clean icon asset/component.
//    No fake white square, no internal oversized transparent canvas.
// ---------------------------------------------------------------------------

write(
  glyph,
  `import { Image } from 'react-native';

const shareArtwork = require(
  '../../assets/ljingle-share-icon-clean.png',
);

type Props = {
  size?: number;
};

export function ShareGlyph({
  size = 25,
}: Props) {
  return (
    <Image
      resizeMode="contain"
      source={shareArtwork}
      style={{
        width: size,
        height: size,
      }}
    />
  );
}
`,
);

// ---------------------------------------------------------------------------
// 2) Entry TS error — add disabled style if share still references it.
// ---------------------------------------------------------------------------

{
  let text = read(entry);

  if (
    text.includes('styles.disabled') &&
    !text.includes('  disabled:')
  ) {
    const pressed = text.indexOf('  pressed:');

    if (pressed >= 0) {
      text =
        text.slice(0, pressed) +
        '  disabled: { opacity: 0.45 },\n' +
        text.slice(pressed);
    } else {
      const close = text.lastIndexOf('});');
      if (close < 0) fail('Entry StyleSheet close missing');

      text =
        text.slice(0, close) +
        '  disabled: { opacity: 0.45 },\n' +
        text.slice(close);
    }
  }

  write(entry, text);
}

// ---------------------------------------------------------------------------
// 3) Share should look like Jingle: icon only, directly beside title.
// ---------------------------------------------------------------------------

function cleanPortableShare(file) {
  let text = read(file);

  text = replaceStyleObject(
    text,
    'portableTitleRow',
    `  portableTitleRow: {
    marginTop: 2,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'flex-start',
    gap: 8,
  },`,
  );

  text = replaceStyleObject(
    text,
    'portableTitleText',
    `  portableTitleText: {
    flexShrink: 1,
    minWidth: 0,
  },`,
  );

  text = replaceStyleObject(
    text,
    'portableShare',
    `  portableShare: {
    width: 30,
    height: 30,
    padding: 0,
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 0,
    borderRadius: 0,
    backgroundColor: 'transparent',
  },`,
  );

  write(file, text);
}

cleanPortableShare(collection);
cleanPortableShare(entry);
cleanPortableShare(topic);

// Frequency uses a different style key but same visual rule.
{
  let text = read(radio);

  text = replaceStyleObject(
    text,
    'frequencyShare',
    `  frequencyShare: {
    width: 30,
    height: 30,
    padding: 0,
    alignItems: 'center',
    justifyContent: 'center',
    borderWidth: 0,
    borderRadius: 0,
    backgroundColor: 'transparent',
  },`,
  );

  write(radio, text);
}

console.log('');
console.log('SHARE CLEAN V2 INSTALLED');
console.log('✓ fixed EntryForm styles.disabled TS error');
console.log('✓ cropped noisy transparent padding from your share artwork');
console.log('✓ share is now icon-only like Jingle');
console.log('✓ removed share border / white button shell');
console.log('✓ Collection / Topic / Zapis share sits directly beside title');
console.log('✓ Frequency share keeps its own icon-only position');
console.log('✓ Link keeps a separate visual language');
console.log('BACKUP:', backupDir);
console.log('');

try {
  cp.execSync('npx tsc --noEmit', {
    cwd: MOBILE,
    stdio: 'inherit',
    shell: true,
  });

  console.log('');
  console.log('TYPESCRIPT CLEAN ✓');
} catch {
  console.error('');
  console.error('TYPESCRIPT HAS ERRORS');
  console.error('Backup:', backupDir);
  process.exitCode = 1;
}
